class IndexThreshold(RootModel[str]):
    model_config = ConfigDict(
        regex_engine="python-re",
    )
    root: Annotated[
        str,
        Field(
            description="A threshold of an index: a value of the index strictly between 0 and 1 (WF-REF-0170), as an exact decimal — `0.9`, `0.85`, `0.875`; neither `0` nor `1`. The form is judged first, the range next, each by its constraint: a threshold that is not a decimal (the pattern of `Decimal`: `0,9`, `.5`, `abc`) is refused with 422 `VALIDATION_FAILED`, `fields` designating it (`/index_thresholds/<threshold>`) with `NUMBER_INVALID`; a decimal outside ]0, 1[, which the threshold's pattern refuses (`0`, `1`, `1.5`, `-0.5`), with `THRESHOLD_NOT_BETWEEN_ZERO_AND_ONE`, without a parameter: the interval is open, and has neither a smallest nor a largest admitted value to name. The order of the thresholds (`THRESHOLD_NOT_BELOW_WATCH`) is only judged between thresholds in ]0, 1[.",
            pattern="(?=^-?\\d+(\\.\\d+)?$)(?=^0+\\.\\d*[1-9]\\d*$)",
        ),
    ]


