class DeclaredSubprojectCode(RootModel[str]):
    model_config = ConfigDict(
        regex_engine="python-re",
    )
    root: Annotated[
        str,
        Field(
            description='The code of a declared subproject, under which the ERP knows it, which names its tab in the remaining to commit file (annex B, WF-PRJ-0050): from 1 to 31 characters, never blank, without any of the characters `:`, `\\`, `/`, `?`, `*`, `[` or `]`, and neither "Synthèse" nor "Hors sous-projet", the two tabs that Waterfall names, compared regardless of case — which is what the pattern states (D-7, EP-16/US-0610). A write that does not respect it is refused with 422 `VALIDATION_FAILED`, `fields` designating `/code`: too long, with `VALUE_TOO_LONG`, `fields[].params.max_length` at `31`, the bound that every `VALUE_TOO_LONG` carries; containing a forbidden character, with `SUBPROJECT_CODE_INVALID`, `fields[].params.forbidden_characters` the forbidden characters it contains, each once, in the order in which the code contains them; equal to a reserved name, with `SUBPROJECT_CODE_INVALID`, `fields[].params.reserved_name` that name as Waterfall writes it. The code read in the WBS element of an actual cost line (`ActualCostLine.subproject_code`) is not this one and keeps its bound of 50: a line with an unknown code is kept as is (WF-CRE-0020).',
            max_length=31,
            min_length=1,
            pattern="^(?![Ss][Yy][Nn][Tt][Hh][Èè][Ss][Ee]$|[Hh][Oo][Rr][Ss] [Ss][Oo][Uu][Ss]-[Pp][Rr][Oo][Jj][Ee][Tt]$)[^:\\\\/?*\\[\\]]*[^:\\\\/?*\\[\\]\\s][^:\\\\/?*\\[\\]]*$",
        ),
    ]


