    finish: WorkInstant | None = None
    progress: TaskProgress | None = None
    finish_overdue: Annotated[
        bool | None,
        Field(
            description="Computed: true for a started task whose finish is earlier than the calculation date, which the remaining-to-commit grid flags (WF-RAE-0040). False otherwise."
        ),
    ] = None
    awaiting_own_lines: Annotated[
        bool | None,
        Field(
            description="Computed, always returned: true for a started summary task all of whose subordinates are completed and one of whose own non-provision lines keeps a remaining to commit (WF-PLA-0040); the remaining-to-commit grid and the Kanban flag it, as well as its own non-provision lines, the only open lines of the phase, according to the common scale (WF-IHM-0070). False for any other task. The flag of the lines is carried by their task: the front flags the own non-provision lines of a task whose flag is true (F-05, #1774)."
        ),
    ] = None
    started_on: Annotated[
        PlanningDate | None,
        Field(
            description="Start date, set at the change of state (WF-PLA-0130), null for a task not started. A task completed without having been started — a milestone completed from the Kanban, a task that the entry of a zero remaining to commit completes — takes as its start date that of its completion; a reopened milestone loses both (`ProgressUpdate`). A summary task carries that of the first of its started subordinates. A read column of the planning grid (`NodeColumn.started_on`, WF-PLA-0080)."
        ),
    ] = None
    completed_on: Annotated[
        PlanningDate | None,
        Field(
            description="Completion date, which places the earned value in time (WF-IND-0030), null for a task that is not completed. A summary task carries the latest of the completion dates of its subordinates and of the setting to zero of its own lines outside provision (WF-PLA-0130). A read column of the planning grid (`NodeColumn.completed_on`, WF-PLA-0080)."
        ),
    ] = None
    is_summary: Annotated[
        bool | None,
        Field(
            description="Summary task: its state is derived from its subordinates, not enterable (WF-PLA-0040)."
        ),
    ] = None
    is_milestone: Annotated[
        bool | None, Field(description="Milestone, a task of zero duration (WF-PLA-0050).")
    ] = None
    calendar_id: Annotated[
        Uuid | None,
        Field(
            description="Applicable calendar, resolved on read: intersection of the calendars of the roles of the labour lines, or default calendar (WF-PLA-0010). Null when it is the intersection of several calendars, which has no identifier: `calendar_hours` then carries its hours."
        ),
    ] = None
    calendar_hours: Annotated[
        WeeklyHours | None,
        Field(
            description="Computed, never entered: the hours of each day of the week of the calendar applicable to the task, the one on which its dates and its duration are counted (WF-PLA-0010) — each day, the smallest of the numbers of hours that the calendars of the roles of its labour lines grant it; the default calendar if it carries none. A summary task and a milestone follow the same rule, on only the lines they carry: a summary task does not inherit the calendars of its subordinates, each of which has its own, and its dates as well as its duration are counted on its own (WF-PLA-0040). A day at 0 hours is a non-working day of the task, which the Gantt distinguishes; the contract knows no public holidays (WF-REF-0110). On a marked revision, the hours of the calendars it freezes (`EmployedReference`)."
        ),
    ] = None
    total_float: Annotated[
        Duration | None,
        Field(
            description="Total float (WF-PLA-0100), computed: working time in working days (`unit: d`), decimal and signed, without minimum. A manual task bounds the late finish of its predecessors as well as the early start of its successors: a predecessor that cannot finish in time for it carries a negative float, it is critical, and the conflicting link is named on both tasks (`link_conflicts`, WF-PLA-0020). Null for a manual task, which carries no float. A summary task carries the smallest float of those of its subordinates that carry one, null when none carries one (WF-PLA-0100): one that carries a critical subordinate displays that subordinate's float, zero or negative."
        ),
    ] = None
    is_critical: Annotated[
        bool | None,
        Field(
            description="Membership of the critical path, computed: a zero or negative total float (WF-PLA-0100). False for a manual task, which never appears on the critical path; true for a summary task as soon as one of its subordinates is critical."
        ),
    ] = None
    link_conflicts: Annotated[
        list[LinkConflict] | None,
        Field(
            description="The conflicting links (WF-PLA-0020), always returned, empty without conflict: on a manual task, those that its automatic predecessors cannot satisfy; on such a predecessor, those it does not satisfy. Each one names its two tasks and its type, in outline order of their predecessor, then of their successor; the grid and the Gantt flag both tasks according to the common scale (WF-IHM-0070) without cross-checking the floats or recomputing any date (WF-ARC-0020). A summary task carries none. Computed, never entered, they disappear as soon as the dates allow; a write that creates or lifts some returns them (`NodesWritten.rescheduled`)."
        ),
    ] = None
    physical_progress: Annotated[
        Computable | None,
        Field(
            description='Physical progress of a summary task, computed: the ratio of the budgeted amounts earned in its subtree — its own lines included, earned when it is completed, provision lines excluded (WF-IND-0030) — to the total of the budgeted amounts of that subtree, provision lines excluded (WF-IND-0060), to four decimal places (README, "A share…"), not computable when that total is zero (`no_budgeted_amount`, WF-IND-0010). Null for a task that is not a summary task.'
        ),
    ] = None
    base_amount: Annotated[
        Money | None,
        Field(
            description="Sum of the amounts at the rates of the reference year, before inflation, of the lines that the task carries and of those of its subordinates, computed by the server, never enterable: a read value, which the estimate grid presents for a task, summary task included (WF-DEV-0050). An attribute of the task: a grid filter does not change it, like the two sums that follow."
        ),
    ] = None
    budgeted_amount: Annotated[
        Money | None,
        Field(
            description="Same sum, for the budgeted amounts, inflation included, at the consumption year of each line (WF-DEV-0020)."
        ),
    ] = None
    reestimated_amount: Annotated[
        Money | None,
        Field(
            description="Same sum, for the re-estimated amounts, inflation included, at the consumption year of each line (WF-DEV-0020, WF-DEV-0050)."
        ),
    ] = None
    tracking: Annotated[
        list[TrackingEntry] | None,
        Field(description="Registrations to timelines and to time/time tracking (WF-PLA-0060)."),
    ] = None
    order_item_id: Annotated[
        Uuid | None,
        Field(
            description='The order item of the work breakdown that this task carries (WF-PLA-0170), under the same rules as `work_package_id`, exclusive of it: a task carries a work package or an order item, never both; an order item is carried by only one task at a time. "When the work package of an order item is attached, the task of that order item lies in the subtree of the task of that work package" (WF-PLA-0170). The grids filter by order item on this attachment (WF-DEV-0050, WF-RAE-0040). Null when the task carries no order item.'
        ),
    ] = None
    work_package_id: Annotated[
        Uuid | None,
        Field(
            description="The work package of the work breakdown that this task carries, summary or leaf (WF-PLA-0170): set by the skeleton (WF-PRJ-0030), modifiable and removable, exclusive of `order_item_id`. A work package is carried by only one task at a time; it is through it that the estimate presents the total per work package, that of its subtree (WF-DEV-0060), and that the grids filter by work package. A summary task that loses its last subordinate keeps its attachment. Null without attachment."
        ),
    ] = None
    work_breakdown_label: Annotated[
        str | None,
        Field(
            description="The label of the work package or order item carried, resolved on read, which the `work_breakdown` column presents without the grid reading the work breakdown (WF-ARC-0020); null without attachment."
        ),
    ] = None
    external_id: Annotated[
        ExternalId | None,
        Field(
            description="The identifier that MS Project gave the task in the file whose import created it, kept as an external identifier (WF-INTF-0040): it is through it that a file reworked before the first export is matched to the task. Null for a task created in Waterfall, never entered."
        ),
    ] = None


