class StructureMergeReport(ContractModel):
    main_structure_lock_version: Annotated[
        LockVersion,
        Field(
            description="The counter of the main structure read (`CostStructure.lock_version`): an entry that writes it since makes the report stale, and the confirmation is refused with 412."
        ),
    ]
    amendment_lock_version: Annotated[
        LockVersion,
        Field(
            description="The counter of the differential read (`CostStructure.lock_version`), likewise."
        ),
    ]
    creates_current_revision: Annotated[
        bool,
        Field(
            description='True when the project has no current revision: the differential is that of the last marked revision, and the merge first creates the current revision by copying it, priced at the kept rates, projected, merges the copy of the differential into it and marks it, in the same background task — "When the project has no current revision, it first creates one" (WF-REV-0050, WF-REV-0010, WF-REV-0060; #790). Its differences and its refusal reasons are then judged on the main structure of the marked revision, which the copy takes over as is, and its counters are those of its structures, which the marking froze. False for a differential of the current revision.'
        ),
    ]
    differences: Annotated[
        list[ImportDifference],
        Field(
            description="The differences of the differential with the main structure, tasks, estimate lines and links, like those of an import (`ImportDifference`); an addition has no lineage yet in the main structure. The provision line of a risk whose carrying task the differential removes moves to another task, and the report flags it with an `updated` difference of the line on `parent` (WF-RIS-0010; #789). An `updated` difference of a line names the figures that the differential gives it (`fields`): they become its reference figures, and also its current figures when its task is not started and nobody has re-estimated it (WF-REV-0050); the report does not distinguish the two cases, the re-estimated state of a line remaining with the server (US-0701/L1, M-08)."
        ),
    ]
    completed_tasks: Annotated[
        list[ImportCompletedTask],
        Field(
            description="The started tasks that the differential removes, which the merge completes by bringing their remaining to commit to zero (WF-REV-0050, WF-RAE-0040)."
        ),
    ]
    refusals: Annotated[
        list[ReportRefusal],
        Field(
            description="The reasons that refuse the whole merge (WF-PLA-0010, WF-PLA-0030, WF-PLA-0150, WF-PLA-0170), each with the parameters it carries when the merge fails (`ReportRefusal`). Empty when the merge applies. A link loop (`LINK_CYCLE`) leaves the structure's dates uncomputed: the horizon is then not judged, and `PROJECT_HORIZON_EXCEEDED` never accompanies it (#788)."
        ),
    ]


