    mitigation_notes: Annotated[str | None, Field(description="Null when none is entered.")]
    probability: Percent
    severity: Annotated[Money, Field(description="Computed, never entered (WF-RIS-0010).")]
    provision_amount: Annotated[
        Money,
        Field(
            description="For an identified risk, its current provision, the severity weighted by the probability, which its provision line carries. For an occurred or dismissed risk, which no longer carries a line, the provision it held in the reference revision, `0.00` if it was not identified there (WF-RIS-0040, WF-RIS-0050): the register row thus sums into the totals (`ProvisionTotals`). Never in the reference budget (WF-RIS-0050)."
        ),
    ]
    occurrence_cost: Annotated[
        Money | None,
        Field(
            description="The cost at occurrence of an occurred risk: the total of its own estimate at the moment it was declared occurred, which neither the re-estimations nor the completion of the merged tasks change, and which the coverage compares with the reserve (WF-RIS-0010, WF-RIS-0050, WF-RIS-0060; `RiskCoverageTotals.occurred_cost`). A revision data item, which abandoning the revision in which the risk occurred erases (WF-RIS-0020). Null for an identified or dismissed risk."
        ),
    ]
    occurred_reestimated_amount: Annotated[
        Money | None,
        Field(
            description="For an occurred risk, the sum of the current reestimated amounts, inflation included, of the lines of the revision read that came from it (`Node.origin_risk_id`, WF-RIS-0060): what the lines that its occurrence merged cost today, which the register presents alongside the cost at occurrence (`occurrence_cost`) to show its drift. Information outside the coverage, whose variance remains computed on the cost at occurrence (`RiskCoverageTotals.occurred_reestimated`, WF-RIS-0050; #1761). Null for an identified or dismissed risk."
        ),
    ]
    state: RiskState
    structure_id: Annotated[
        Uuid,
        Field(
            description="The risk's own cost structure, in the revision read (`revision_id`), which freezes a version of it (WF-RIS-0030)."
        ),
    ]
    provision_node_id: Annotated[
        Uuid | None,
        Field(
            description="Provision line carried by the main structure (WF-RIS-0010). Null when the risk is not identified — occurred or dismissed —: it then carries no provision line."
        ),
    ]
    provision_cost_category_id: Annotated[
        Uuid,
        Field(
            description="The category of the provision-for-risks type that the risk designated for its provision — at its declaration, or since, while it was identified —, which its provision line carries while it is identified (WF-RIS-0010, WF-REF-0030). A dismissed risk keeps it: once identified again, its line takes it back if it is still active and of the provision-for-risks type, and otherwise the category is asked for as at the declaration (`RiskReviewWrite.provision_cost_category_id`), which `provision_cost_category_is_active` states in advance."
        ),
    ]
    provision_cost_category_label: Annotated[
        str,
        Field(
            description="The label of this category, resolved at read time, active or deactivated, which the register and the form present without reading the reference data (WF-ARC-0020, WF-REF-0150)."
        ),
    ]
    provision_cost_category_is_active: Annotated[
        bool,
        Field(
            description='Computed at read time: true when this category is active and its cost type is of the provision-for-risks type — its cost type is then active too, deactivating a cost type deactivating its categories (WF-REF-0010; EP-14/L42s, C-291). False for a deactivated category, or one attached since to a cost type of another type: a category that no line uses any more, that of a dismissed risk, can change cost type (WF-REF-0030), and it is then no longer "among the active categories of the provision-for-risks type" (WF-RIS-0010; #747). When false, the return of the dismissed risk to the identified state asks for another category (`RiskReviewWrite.provision_cost_category_id`, WF-RIS-0010): the front reads it, without comparing the category with the lists of the reference data.'
        ),
    ]
    provision_subproject_id: Annotated[
        Uuid | None,
        Field(
            description='The subproject that the risk designated, optionally, for its provision, and to which its provision line belongs; when null, the line counts in the "hors sous-projet" set (WF-RIS-0010, WF-RAE-0020, WF-IND-0020). Deleting the subproject sets to null the designation of every risk that is not identified: once identified again, its provision counts outside any subproject — the author settled this on 2026-10-10 (author\'s decision, #732). The affected risk then has its `lock_version` advance and its audit name the author of the deletion (WF-DAT-0070, WF-IHM-0110).'
        ),
    ]
    provision_subproject_label: Annotated[
        str | None,
        Field(
            description="The label of this subproject, resolved at read time; null for a provision outside any subproject."
        ),
    ]
    provision_task: Annotated[
        ProvisionTask | None,
        Field(
            description="The task of the main structure of the revision read that carries the provision line (`provision_node_id`), by its node and its label, resolved at read time: the one the risk designated at its declaration or since, while it was identified, and failing that the first top-level task (WF-RIS-0010, #786). A dismissed risk that becomes identified again gets back the task it designated if that is still a task of the main structure, and otherwise the first top-level task (`reviewRisk`, #1227). The form presents it and offers it again without reading the structure again (WF-ARC-0020). Null when the risk is not identified: it then carries no provision line."
        ),
    ]
    matrix_cell: RiskMatrixCell
    last_review_on: Annotated[
        PlanningDate | None,
        Field(
            description="The day of its last review, which the grid presents (WF-RIS-0040): its declaration, a review (`reviewRisk`) or its occurrence."
        ),
    ]
    computed_fields: Annotated[
        list[RiskComputedField],
        Field(
            description="The fields of the risk that the server computes, each with what it depends on, which the refusal of an entry names (WF-IHM-0030): the severity and the provision, in that order, for every risk, then the cost at occurrence of an occurred risk. The severity depends on the own estimate (`own_estimate`); the provision of an identified risk, on its severity and its probability (`severity_and_probability`), that of an occurred or dismissed risk, on the reference revision (`reference_provision`); the cost at occurrence, on the own estimate at the moment of the occurrence (`occurrence_estimate`). The rules of the computation, not the lines of the own estimate: they are read with the risk, without calling on the refusal.",
            max_length=3,
            min_length=2,
        ),
    ]
    available_commands: Annotated[
        list[RiskCommandAvailability],
        Field(
            description="Commands of the risk that the caller has permission to exercise, each available or not, with the conditions it lacks (WF-IHM-0090), in the order of `RiskCommand`. A command absent from the list is not presented. The risk names only what depends on it — its state, its citation by a marked revision — and, for the occurrence, the revision that the occurrence would create; the conditions of the project and of the revision are on their commands (`ProjectCommand.declare_risk_occurrence`, `RevisionCommand.edit_risks`). The risk of a terminal project lists none (US-0702/L3). A call sent despite the list is refused with its error code."
        ),
    ]
    audit: Audit
    lock_version: Annotated[
        LockVersion,
        Field(
            description="Lock version of the risk, a single one for its identity and its assessment: it advances on each write of the risk — the change of its identity (`updateRisk`) as well as the change of its provision (`updateRiskProvision`) —, and never goes back: abandoning a revision advances it, the assessment read changing (H-02, #1782). It also advances on any entry in its own estimate (`structure_id`) — a cell, a paste, a move, a creation, a deletion —, from which it takes its severity (WF-RIS-0010): the report of its occurrence, which describes that estimate, is thus made stale by such an entry (`RiskOccurrence`). It likewise advances when the subproject it designated is deleted (`provision_subproject_id`, #732)."
        ),
    ]


