class RiskOccurrenceReport(ContractModel):
    main_structure_lock_version: Annotated[
        LockVersion,
        Field(
            description="The lock version of the main structure read (`CostStructure.lock_version`) — that of the current revision, or, without a current revision, that of the last marked revision: an entry that writes to it since makes the report stale, and the confirmation is refused with 412."
        ),
    ]
    risk_lock_version: Annotated[
        LockVersion,
        Field(
            description="The lock version of the risk read (`Risk.lock_version`), likewise. It also advances on any entry in the risk's own estimate, whose tasks and lines the report lists: an entry that writes to it since makes the report stale."
        ),
    ]
    creates_current_revision: Annotated[
        bool,
        Field(
            description='True when the project has no current revision: the occurrence first creates the current revision by copying the last marked revision, priced at the kept rates, projected, then merges the own estimate into it, in the same background task — "When the project has no current revision, it creates one beforehand" (WF-RIS-0060, WF-REV-0010, WF-REV-0060). Its differences and its grounds for refusal are then judged on the main structure of the marked revision, which the copy takes over as is, and `main_structure_lock_version` is the lock version of that structure, which the marking froze, as for the merge of a differential (`StructureMergeReport.creates_current_revision`, #790) and as the risk is read (`getRisk`, `revision_id` absent). False when the project has a current revision. A current revision born since the read has the confirmation refused with 412.'
        ),
    ]
    differences: Annotated[
        list[ImportDifference],
        Field(
            description="The differences that the occurrence would make in the main structure, like those of a merge (`ImportDifference`), in this order: the tasks and the lines of the own estimate, added (`added`) in the order of its plan — its top-level tasks in last position under the task that carries the provision line, or, when that is a milestone, immediately after it, under its parent task or at the top level; an addition has no lineage yet, and the internal links of the own estimate come with its tasks —; the carrying task changed (`updated`), now the summary task of these tasks, `fields` naming what changes about it, its dates and its duration now covering those of its subordinates (WF-PLA-0040) — a milestone, which remains a milestone without subtasks, is not changed —; the provision line removed (`removed`). The added tasks keep their subordinates, their internal links, their durations and their modes, a task without a predecessor in the own estimate switching to manual mode at the dates it had there; the added lines take a zero budgeted amount (WF-RIS-0060)."
        ),
    ]
    provision_amount: Annotated[
        Money,
        Field(
            description="The amount of the removed provision line, which leaves the remaining to commit — the provision of the risk (`Risk.provision_amount`); the remaining to commit increases by the total of the own estimate, minus this amount (WF-RIS-0060)."
        ),
    ]
    refusals: Annotated[
        list[ReportRefusal],
        Field(
            description="The grounds that refuse the whole occurrence, each with the parameters it carries when the background task fails (`ReportRefusal`) — such as `TASK_WITHOUT_WORKING_HOURS`, a merged task one of whose labour lines has a role without any working hour in the week (WF-PLA-0010). Empty when the occurrence applies."
        ),
    ]


